mapper.select:
SELECT e.id AS record_id, e.equipment_id AS equipment_id, eq.equipment_name AS equipment_name, eq.fixed_asset_code AS fixed_asset_code, e.work_order_id AS work_order_id, wo.work_order_code AS work_order_code, wo.preparation_name AS preparation_name, wo.batch_number AS batch_number, pt.process_name AS process_name, e.start_time AS start_time, e.end_time AS end_time FROM work_order_process_execution e LEFT JOIN equipment eq ON e.equipment_id = eq.equipment_id AND eq.is_deleted = 0 LEFT JOIN work_order wo ON e.work_order_id = wo.work_order_id AND wo.is_deleted = 0 LEFT JOIN process_type pt ON e.process_type_id = pt.process_id AND pt.is_deleted = 0 WHERE e.is_deleted = 0 AND e.equipment_id IN #{eqId} AND e.start_time IS NOT NULL AND e.end_time IS NOT NULL AND e.start_time < #{maxEnd} AND e.end_time > #{minStart}
AND e.id NOT IN #{excludeId}
FOR UPDATE OF e
